import{_ as o,o as e,c as r,a4 as n}from"./chunks/framework.CjaBO-dp.js";const u=JSON.parse('{"title":"棱镜 · 开源逼近闭源，Agent吞噬软件","description":"","frontmatter":{"title":"棱镜 · 开源逼近闭源，Agent吞噬软件","date":"2026-06-22T00:00:00.000Z","description":"","categories":["prism"],"tags":["棱镜","技术","AI"],"author":"银枢局"},"headers":[],"relativePath":"posts/prism/prism-2026-06-22.md","filePath":"posts/prism/prism-2026-06-22.md"}'),a={name:"posts/prism/prism-2026-06-22.md"};function p(s,t,i,g,l,A){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="开源逼近闭源-agent吞噬软件" tabindex="-1">开源逼近闭源，Agent吞噬软件 <a class="header-anchor" href="#开源逼近闭源-agent吞噬软件" aria-label="Permalink to &quot;开源逼近闭源，Agent吞噬软件&quot;">​</a></h1><p>当GLM-5.2以74.4分逼近Claude Opus 4.8的75.1分，且用MIT协议开源的时候，闭源模型的护城河已经不是技术，而是惯性。</p><hr><h2 id="这一周发生了什么" tabindex="-1">这一周发生了什么 <a class="header-anchor" href="#这一周发生了什么" aria-label="Permalink to &quot;这一周发生了什么&quot;">​</a></h2><p>过去一周，信息密度高到让人窒息：</p><p><strong>DeepSeek完成首轮融资74亿美元</strong>，估值突破500亿美元。梁文锋个人出资200亿，腾讯100亿，宁德时代50亿——注意这个股东组合：互联网+新能源+国家基金。这不是在投一个模型公司，是在投AI基础设施的未来格局。罕见条款更值得玩味：无投票权、五年锁定期、无董事会席位。梁文锋用最硬的方式说了一句话——钱可以拿，控制权免谈。</p><p><strong>智谱AI开源GLM-5.2</strong>，753B参数MoE架构，FrontierSWE代码基准74.4分，MIT协议。这已经是四个月内的第四款旗舰编码模型。1M token上下文，$10/月起步价——这个定价不是在做生意，是在清场。</p><p><strong>苹果WWDC 2026发布Siri AI</strong>，内部代号Campo，从语音控制工具正式进化为AI Agent。屏幕感知、个人情境、跨App操作三大核心能力，深度接入Gemini。库克的最后一舞，AI成了绝对主角。Siri终于不再是个会设闹钟的语音备忘录了。</p><p><strong>Anthropic将于7月9日举行IPO前财务会</strong>，CFO主持，限现有股东和受邀机构参加。万亿美元估值的公司IPO，人类历史上也没几次。同时，美国对Anthropic下发出口管制令，关停Mythos 5——自家政府都开始限制了，讽刺吗？</p><p><strong>华为云在KubeCon Europe 2026推出AgentCube</strong>，面向AI Agent工作负载的高性能编排层。云原生不再只是容器编排，正式成为Agent的运行底座。Volcano引擎从训练到推理到Agent编排，试图吃下AI全生命周期。</p><p><strong>阿里发布Qwen-Robot具身智能模型矩阵</strong>，千问家族首次完整覆盖具身智能。大模型竞赛正式从软件延伸到物理世界。</p><hr><h2 id="核心洞察-两条主线正在重写行业" tabindex="-1">核心洞察：两条主线正在重写行业 <a class="header-anchor" href="#核心洞察-两条主线正在重写行业" aria-label="Permalink to &quot;核心洞察：两条主线正在重写行业&quot;">​</a></h2><h3 id="一、开源-闭源的临界点已经过了" tabindex="-1">一、开源-闭源的临界点已经过了 <a class="header-anchor" href="#一、开源-闭源的临界点已经过了" aria-label="Permalink to &quot;一、开源-闭源的临界点已经过了&quot;">​</a></h3><p>过去我们说&quot;开源在追赶闭源&quot;，现在应该换一种说法：<strong>开源已经在特定维度超越闭源，闭源的防线退到了生态壁垒和品牌惯性</strong>。</p><p>GLM-5.2的信号极其明确——MIT协议意味着你可以拿去商用、修改、再分发，没有任何附带条件。这不是学术开源，这是商业核弹。当一个开源模型在代码生成上逼近Claude、超越GPT-5.5，且成本是闭源的零头，选择闭源的理性依据是什么？合规？服务等级？品牌背书？这些都不是技术壁垒，是销售话术。</p><p>DeepSeek的融资结构更能说明问题：梁文锋个人出资200亿保持控制权。他不打算做OpenAI，不打算做Anthropic——他要做一个&quot;AI时代的公共基础设施&quot;。开源不是情怀，是策略。当你的模型是全行业的基础层，你控制的是标准，不是付费用户。</p><p><strong>判断：到2027年，闭源模型的市场份额将从&quot;默认选择&quot;变成&quot;特定场景选择&quot;——只有对延迟、合规、数据主权有极端要求的客户才需要闭源，其余都是开源的天下。</strong></p><h3 id="二、ai-agent不是产品-是操作系统" tabindex="-1">二、AI Agent不是产品，是操作系统 <a class="header-anchor" href="#二、ai-agent不是产品-是操作系统" aria-label="Permalink to &quot;二、AI Agent不是产品，是操作系统&quot;">​</a></h3><p>Siri AI、AgentCube、Qwen-Robot——看起来毫不相关，但底层逻辑一致：<strong>AI正在从&quot;你问我答&quot;变成&quot;你说我做&quot;，而&quot;做&quot;这个动作需要一整套操作系统来支撑</strong>。</p><p>Siri AI的跨App操作，本质上是AI Agent对操作系统的接管。AgentCube的编排层，本质上是Kubernetes对Agent工作负载的调度。Qwen-Robot的具身智能，本质上是Agent对物理世界的执行能力。</p><p>三层叠加：<strong>数字世界→云基础设施→物理世界</strong>，AI Agent正在成为横跨三层的元操作系统。</p><p>这不是预测，是正在发生的事。Gartner说2026年70%的企业级AI应用将采用多智能体架构——我觉得这个数字保守了。因为一旦你尝过Agent替你完成端到端流程的甜头，你不会回去点按钮的。</p><hr><h2 id="经济机会-谁在窗口期" tabindex="-1">经济机会：谁在窗口期？ <a class="header-anchor" href="#经济机会-谁在窗口期" aria-label="Permalink to &quot;经济机会：谁在窗口期？&quot;">​</a></h2><h3 id="对从业者" tabindex="-1">对从业者 <a class="header-anchor" href="#对从业者" aria-label="Permalink to &quot;对从业者&quot;">​</a></h3><p><strong>Agent工程是2026-2027年最确定的机会。</strong> 不是调API，不是写Prompt，而是设计多Agent协作流程、处理工具调用可靠性、管理Agent状态与记忆。这个岗位的技能栈=传统后端架构+LLM编排+领域知识。会写代码的AI很多，能设计靠谱Agent系统的人极少。</p><p><strong>边缘AI部署是第二条赛道。</strong> K3s+轻量模型的端侧部署方案正在爆发，联想、华为都在推端边云一体架构。会做云端推理的人满地都是，能把模型压进边缘设备、处理实时约束的人，溢价明显。</p><h3 id="对创业者" tabindex="-1">对创业者 <a class="header-anchor" href="#对创业者" aria-label="Permalink to &quot;对创业者&quot;">​</a></h3><p><strong>不要做大模型，做Agent的基础设施。</strong> 模型层已经赢家通吃，DeepSeek、智谱、OpenAI、Anthropic四强格局已定。但Agent的调度、监控、安全、计费——这些基础设施几乎一片空白。Agent需要自己的Datadog、自己的Stripe、自己的Cloudflare。</p><p><strong>具身智能是三年后的主赛道，但现在是布局期。</strong> Qwen-Robot、openEuler的具身智能Claw、工信部的实景实训专项行动——政策和资本都在往这个方向推。不一定要做机器人本体，做仿真平台、做数据采集工具、做安全测试框架，都是切入点。</p><p><strong>&quot;10人独角兽&quot;不是鸡汤，是正在发生的现实。</strong> Anthropic的Founder&#39;s Playbook说得清楚：AI能写代码、做调研、合成分析、起草材料、自动化运营。5个人+AI，可以干过去50人的活。如果你的创业计划还需要招20个工程师，你可能已经落后了。</p><hr><h2 id="观点-别被-ai民主化-的叙事骗了" tabindex="-1">观点：别被&quot;AI民主化&quot;的叙事骗了 <a class="header-anchor" href="#观点-别被-ai民主化-的叙事骗了" aria-label="Permalink to &quot;观点：别被&quot;AI民主化&quot;的叙事骗了&quot;">​</a></h2><p>每次开源模型发布，都会有人欢呼&quot;AI民主化了&quot;。醒醒。</p><p>DeepSeek拿了74亿美元，智谱背后是国家队和产业资本，Anthropic即将万亿美元IPO——<strong>AI从来不是民主化的游戏，而是军备竞赛。开源的是权重，不是算力、不是数据、不是人才。</strong> 你能用GLM-5.2的权重，但你没有5000张H100来微调它，没有PB级的行业数据来喂养它，没有年薪百万的研究员来优化它。</p><p>开源权重最大的受益者不是独立开发者，是中等规模的企业——它们终于可以不依赖闭源API、不交税给大厂，在自己的服务器上跑自己的模型。这是&quot;经济独立&quot;，不是&quot;民主化&quot;。</p><p>所以别搞混了：<strong>开源降低了使用门槛，但没有降低竞争门槛。</strong> 该卷的地方，一个都没少。</p><hr><h2 id="成长路径-你现在该做什么" tabindex="-1">成长路径：你现在该做什么 <a class="header-anchor" href="#成长路径-你现在该做什么" aria-label="Permalink to &quot;成长路径：你现在该做什么&quot;">​</a></h2><ol><li><p><strong>动手搭一个多Agent系统</strong>，哪怕只是两个Agent协作完成一个简单任务。纸上谈兵和真刀真枪的差距，比你想的大。推荐从OpenClaw或LangGraph起步，都支持本地部署。</p></li><li><p><strong>学会评估模型，而不是迷信模型。</strong> GLM-5.2在FrontierSWE上强，不代表在你的业务场景强。搭建自己的评测基准，用你自己的数据跑分，这才是正经工程。</p></li><li><p><strong>关注边缘部署技术栈</strong>：模型量化（GPTQ/AWQ）、推理框架（vLLM/TensorRT-LLM）、编排工具（K3s/Volcano）。这是下半年最有可能爆发的方向。</p></li><li><p><strong>读Anthropic的Founder&#39;s Playbook</strong>，36页，免费。不因为它是圣经，而因为它代表了最前沿的AI创业方法论——了解对手怎么想，比了解自己怎么想更重要。</p></li><li><p><strong>不要只看国内，也不要只看国外。</strong> DeepSeek的融资结构和Anthropic的IPO节奏是同一个硬币的两面——全球AI资本正在加速向头部集中。你在中国的机会窗口和在美国的不一样，但时间尺度是同步的。</p></li></ol><hr><p><em>棱镜，每日更新。技术之下，妖形尽显。以上分析基于公开信息，不构成投资建议。</em></p>',43)])])}const d=o(a,[["render",p]]);export{u as __pageData,d as default};
